    61  /**
    62   * This class implements Thread Network Data TLV generation and parsing.
    63   *
    64   */
    65  OT_TOOL_PACKED_BEGIN
    66  class NetworkDataTlv
    67  {
    68  public:
    69      /**
    70       * This method initializes TLV.
    71       *
    72       */
    73      void Init(void)
    74      {
    75          mType   = 0;
    76          mLength = 0;
    77      }
    78
    79      /**
    80       * Thread Network Data Type values.
    81       *
    82       */
    83      enum Type
    84      {
    85          kTypeHasRoute          = 0, ///< Has Route TLV
    86          kTypePrefix            = 1, ///< Prefix TLV
    87          kTypeBorderRouter      = 2, ///< Border Router TLV
    88          kTypeContext           = 3, ///< Context TLV
    89          kTypeCommissioningData = 4, ///< Commissioning Dataset TLV
    90          kTypeService           = 5, ///< Service TLV
    91          kTypeServer            = 6, ///< Server TLV
    92      };
    93
    94      /**
    95       * This method returns the Type value.
    96       *
    97       * @returns The Type value.
    98       *
    99       */
   100      Type GetType(void) const { return static_cast<Type>(mType >> kTypeOffset); }
   101
   102      /**
   103       * This method sets the Type value.
   104       *
   105       * @param[in]  aType  The Type value.
   106       *
   107       */
   108      void SetType(Type aType) { mType = (mType & ~kTypeMask) | ((aType << kTypeOffset) & kTypeMask); }
   109
   110      /**
   111       * This method returns the Length value.
   112       *
   113       * @returns The Length value.
   114       *
   115       */
   116      uint8_t GetLength(void) const { return mLength; }
   117
   118      /**
   119       * This method sets the Length value.
   120       *
   121       * @param[in]  aLength  The Length value.
   122       *
   123       */
   124      void SetLength(uint8_t aLength) { mLength = aLength; }
   125
   126      /**
   127       * This method returns a pointer to the Value.
   128       *
   129       * @returns A pointer to the value.
   130       *
   131       */
   132      uint8_t *GetValue(void) { return reinterpret_cast<uint8_t *>(this) + sizeof(NetworkDataTlv); }
   133
   134      /**
   135       * This method returns a pointer to the next Network Data TLV.
   136       *
   137       * @returns A pointer to the next Network Data TLV.
   138       *
   139       */
   140      NetworkDataTlv *GetNext(void)
   141      {
   142          return reinterpret_cast<NetworkDataTlv *>(reinterpret_cast<uint8_t *>(this) + sizeof(*this) + mLength);
   143      }
   144
   145      /**
   146       * This method clears the Stable bit.
   147       *
   148       */
   149      void ClearStable(void) { mType &= ~kStableMask; }
   150
   151      /**
   152       * This method indicates whether or not the Stable bit is set.
   153       *
   154       * @retval TRUE   If the Stable bit is set.
   155       * @retval FALSE  If the Stable bit is not set.
   156       *
   157       */
   158      bool IsStable(void) const { return (mType & kStableMask); }
   159
   160      /**
   161       * This method sets the Stable bit.
   162       *
   163       */
   164      void SetStable(void) { mType |= kStableMask; }
   165
   166  private:
   167      enum
   168      {
   169          kTypeOffset = 1,
   170          kTypeMask   = 0x7f << kTypeOffset,
   171          kStableMask = 1 << 0,
   172      };
   173      uint8_t mType;
   174      uint8_t mLength;
   175  } OT_TOOL_PACKED_END;
